soil_moisture = [45, 38, 29, 22, 41]   # har ghante sensor ki reading (%)
dry_limit = 30                         # is se kam nami = zameen sookhi
room_temp = 36                         # kamre ka darja hararat (°C)

for hour, reading in enumerate(soil_moisture, start=1):
    if reading < dry_limit:
        print(f"Ghanta {hour}: nami {reading}% -> pump ON (pani shuru)")
    else:
        print(f"Ghanta {hour}: nami {reading}% -> pump OFF")

if room_temp > 35:
    print("Darja hararat", room_temp, "-> parde band")
else:
    print("Darja hararat", room_temp, "-> parde khule")
